test "pinned plural families select Arabic and Slavic positional categories" {
    const Case = struct { code: []const u8, count: []const u8, expected: usize };
    const cases = [_]Case{
        .{ .code = "ar", .count = "0", .expected = 0 },
        .{ .code = "ar", .count = "1", .expected = 1 },
        .{ .code = "ar", .count = "2", .expected = 2 },
        .{ .code = "ar", .count = "3", .expected = 3 },
        .{ .code = "ar", .count = "11", .expected = 4 },
        .{ .code = "ar", .count = "100", .expected = 5 },
        .{ .code = "ar", .count = "3.5", .expected = 5 },
        .{ .code = "ru", .count = "1", .expected = 0 },
        .{ .code = "ru", .count = "2", .expected = 1 },
        .{ .code = "ru", .count = "5", .expected = 2 },
        .{ .code = "ru", .count = "11", .expected = 2 },
        .{ .code = "ru", .count = "21", .expected = 0 },
        .{ .code = "ru", .count = "22", .expected = 1 },
        .{ .code = "ru", .count = "1.5", .expected = 3 },
        .{ .code = "pl", .count = "1", .expected = 0 },
        .{ .code = "pl", .count = "2", .expected = 1 },
        .{ .code = "pl", .count = "12", .expected = 2 },
        .{ .code = "pl", .count = "22", .expected = 1 },
    };
    for (cases) |case| try std.testing.expectEqual(case.expected, index(case.code, case.count).?);
}

test "plural operands preserve fraction relations and MediaWiki overrides" {
    try std.testing.expectEqual(@as(usize, 0), index("en", "1").?);
    try std.testing.expectEqual(@as(usize, 0), index("en", "-1").?);
    try std.testing.expectEqual(@as(usize, 1), index("en", "1.5").?);
    try std.testing.expectEqual(@as(usize, 1), index("en", "1e+20").?);
    try std.testing.expectEqual(@as(usize, 1), index("en", "invalid").?);
    // XML '=' denotes integer set membership: Arabic 3.5 is not in 3..10.
    try std.testing.expectEqual(@as(usize, 5), index("ar", "3.5").?);
    // The pinned French family selects the first form when i is 0 or 1.
    try std.testing.expectEqual(@as(usize, 0), index("fr", "1.5").?);
    try std.testing.expectEqual(@as(usize, 1), index("fr", "2").?);
    const o = operands("-12.340").?;
    try std.testing.expectEqual(@as(f64, 12.34), o.n);
    try std.testing.expectEqual(@as(f64, 12), o.i);
    try std.testing.expectEqual(@as(f64, 3), o.v);
    try std.testing.expectEqual(@as(f64, 2), o.w);
    try std.testing.expectEqual(@as(f64, 340), o.f);
    try std.testing.expectEqual(@as(f64, 34), o.t);
    try std.testing.expect(operands("1e-7") == null);
}

test "empty and absent families require explicit language fallback" {
    try std.testing.expect(hasRules("en"));
    try std.testing.expect(hasRules("ar"));
    try std.testing.expect(!hasRules("ja"));
    try std.testing.expect(!hasRules("aa"));
    try std.testing.expect(!hasRules("unknown-language"));
    try std.testing.expect(index("unknown-language", "2") == null);
    // Literal upstream keys are retained; no language-tag truncation or alias.
    try std.testing.expect(hasRules("pt_PT"));
    try std.testing.expect(!hasRules("pt-PT"));
}
